css:
/* Real occurrence numbers replace the static dates on the illustrated calendar. */
.anniversary-calendar{position:absolute;left:47.5%;top:17.2%;width:34%;height:14.5%;margin:0;padding:1.7cqw 1.2cqw;display:grid;grid-template-rows:auto auto minmax(0,1fr);gap:.8cqw;transform:rotate(7deg);background:#fcf6e9;border-radius:2px;color:#806145;pointer-events:none;font-size:clamp(7px,2.15cqw,10px);line-height:1.25;text-align:center}
.anniversary-calendar[hidden]{display:none}
.anniversary-calendar .calendar-month{font-size:2.7cqw;line-height:1.25}
.anniversary-calendar .calendar-week,.anniversary-calendar .calendar-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));min-height:0}
.anniversary-calendar .calendar-grid>span{display:grid;place-items:center;min-height:0;border:1px solid transparent}
.anniversary-calendar [data-selected="true"]{border-color:#d5997e!important;border-radius:50%;background:#f9e6dc;color:#68432d}
.screen[aria-label="纪念日管理"][data-anniversary-calendar] .hero-title{max-width:36%;font-size:6.8cqw}
.screen[aria-label="纪念日管理"][data-anniversary-calendar] .countdown{width:36%;font-size:min(5.3cqw,21px);line-height:1.3;overflow-wrap:anywhere}
